export const factIds=['ready','blocker','rollback','dependency','reach','budget','date','sentiment'];
export const labels={ready:'Readiness',blocker:'Unresolved blocking defect',rollback:'Rollback available',dependency:'Partner ready',reach:'Trial participants',budget:'Budget remaining',date:'Days to announcement',sentiment:'Positive interviews'};
export const layerNames=['Team update','Portfolio update','Decision brief'];
export const initialState={scenario:'blocker',facts:{ready:92,blocker:true,rollback:true,dependency:true,reach:120,budget:60,date:3,sentiment:8},costs:{ready:1,blocker:2,rollback:1,dependency:1,reach:1,budget:1,date:1,sentiment:1},capacities:[5,4,3],orders:[['ready','reach','budget','blocker','rollback','dependency','date','sentiment'],['ready','budget','reach','blocker','rollback','dependency','date','sentiment'],['ready','reach','budget','blocker','rollback','dependency','date','sentiment']],queries:[],queryDuration:1,decisionWindow:2,threshold:80,unknown:'launch'};
export const scenarios={blocker:{label:'A blocker behind the green update',description:'Readiness is high, but a blocking defect changes the release decision.',facts:{ready:92,blocker:true,rollback:true,dependency:true,reach:120,budget:60,date:3,sentiment:8}},routine:{label:'A routine release',description:'All release conditions are satisfied. A short update can preserve the decision while saving reading.',facts:{ready:92,blocker:false,rollback:true,dependency:true,reach:120,budget:60,date:3,sentiment:8}},fragile:{label:'The fallback is missing',description:'The headline is positive, but rollback is unavailable and the partner is not ready.',facts:{ready:88,blocker:false,rollback:false,dependency:false,reach:60,budget:40,date:1,sentiment:7}}};
const ints={ready:[0,100],reach:[0,1000],budget:[0,100],date:[0,30],sentiment:[0,10]};
function exact(value,keys,label){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).length!==keys.length||keys.some(k=>!Object.hasOwn(value,k)))throw Error(`Invalid ${label}.`);}
function integer(value,min,max,label){if(!Number.isInteger(value)||value<min||value>max)throw Error(`${label} must be an integer from ${min} to ${max}.`);}
export function validate(state){exact(state,Object.keys(initialState),'context model');if(!Object.hasOwn(scenarios,state.scenario))throw Error('Unknown scenario.');exact(state.facts,factIds,'facts');exact(state.costs,factIds,'attention costs');for(const id of factIds){if(ints[id])integer(state.facts[id],...ints[id],id);else if(typeof state.facts[id]!=='boolean')throw Error(`Invalid ${id}.`);integer(state.costs[id],1,4,`${id} cost`);}if(!Array.isArray(state.capacities)||state.capacities.length!==3)throw Error('Three capacities are required.');state.capacities.forEach(c=>integer(c,1,24,'Capacity'));if(!Array.isArray(state.orders)||state.orders.length!==3||state.orders.some(order=>!Array.isArray(order)||order.length!==8||new Set(order).size!==8||order.some(id=>!factIds.includes(id))))throw Error('Each layer needs each fact exactly once.');if(!Array.isArray(state.queries)||state.queries.length>8||new Set(state.queries).size!==state.queries.length||state.queries.some(id=>!factIds.includes(id)))throw Error('Invalid source requests.');integer(state.queryDuration,1,4,'Retrieval time');integer(state.decisionWindow,0,12,'Decision window');integer(state.threshold,0,100,'Readiness threshold');if(!['launch','pilot','hold'].includes(state.unknown))throw Error('Unknown evidence policy.');return state;}
export function loadScenario(state,id){if(!scenarios[id])throw Error('Unknown scenario.');return {...structuredClone(state),scenario:id,facts:structuredClone(scenarios[id].facts)};}
export function valueText(id,value){if(['blocker','rollback','dependency'].includes(id))return value?'Yes':'No';return `${value}${['ready','budget'].includes(id)?'%':''}`;}
// Missing facts are unknown, never inferred from a green headline. The user's
// explicit unknown policy handles the gap; there is no language understanding.
export function decide(facts,threshold,unknown){
  const reasons=[];
  if(facts.blocker===true)reasons.push('A blocking defect is present.');
  if(facts.dependency===false)reasons.push('The partner is not ready.');
  if(Object.hasOwn(facts,'ready')&&facts.ready<threshold)reasons.push(`Readiness ${facts.ready}% is below ${threshold}%.`);
  if(reasons.length)return {choice:'hold',reasons,missing:[]};
  if(facts.rollback===false)return {choice:'pilot',reasons:['There is no rollback: restrict the release to a pilot.'],missing:[]};
  const missing=['ready','blocker','rollback','dependency'].filter(id=>!Object.hasOwn(facts,id));
  if(missing.length)return {choice:unknown,reasons:[`${missing.map(id=>labels[id]).join(', ')} not in view. Apply the explicit unknown-evidence policy: ${unknown}.`],missing};
  return {choice:'launch',reasons:['Readiness meets the threshold; no blocker; partner ready; rollback available.'],missing:[]};
}
export function project(state){validate(state);let available=factIds.slice();const layers=[],lostAt={};let reading=0;for(let i=0;i<3;i++){
  let remaining=state.capacities[i];const carried=[],dropped=[];
  for(const id of state.orders[i])if(available.includes(id)){if(state.costs[id]<=remaining){carried.push(id);remaining-=state.costs[id];}else{dropped.push(id);lostAt[id]=i;}}
  const used=state.capacities[i]-remaining;reading+=used;layers.push({index:i,received:available,carried,dropped,used,remaining});available=carried;
 }
 const report=available.slice(),retrieved=[],unanswered=[],alreadyPresent=[];let queryTime=0;
 for(const id of state.queries){if(available.includes(id)){alreadyPresent.push(id);continue;}if(queryTime+state.queryDuration<=state.decisionWindow){queryTime+=state.queryDuration;available.push(id);retrieved.push(id);}else unanswered.push(id);}
 const seen=Object.fromEntries(available.map(id=>[id,state.facts[id]])),decision=decide(seen,state.threshold,state.unknown),full=decide(state.facts,state.threshold,state.unknown);
 return {layers,report,available,retrieved,unanswered,alreadyPresent,lostAt,reading,queryTime,decision,full,differs:decision.choice!==full.choice};
}
export function prioritize(state,layer,id,to){const next=structuredClone(state),order=next.orders[layer],from=order.indexOf(id);if(from<0||to<0||to>=order.length)return next;order.splice(from,1);order.splice(to,0,id);return next;}
export function decisionFirst(state){const next=structuredClone(state);next.orders=next.orders.map(()=>['blocker','dependency','rollback','ready','reach','budget','date','sentiment']);return next;}
export function compare(state,pinned){if(!pinned)return null;validate(pinned);const replay={...structuredClone(state),capacities:structuredClone(pinned.capacities),orders:structuredClone(pinned.orders),queries:structuredClone(pinned.queries),unknown:pinned.unknown};return {state:replay,result:project(replay),situationChanged:['facts','costs','queryDuration','decisionWindow','threshold'].some(k=>JSON.stringify(state[k])!==JSON.stringify(pinned[k]))};}
export function summary(state,r=project(state)){return `Decision from available facts: ${r.decision.choice}. The same rule with all facts: ${r.full.choice}. ${r.report.length}/8 facts survived; ${r.retrieved.length} retrieved in ${r.queryTime} ticks; ${r.reading} attention units across three reports.`;}
export function describe(state,pinned){const r=project(state),c=compare(state,pinned);return `# What survived the status update?\n\n${summary(state,r)}\n\n${r.layers.map(l=>`${layerNames[l.index]}: carries ${l.carried.map(id=>labels[id]).join(', ')||'nothing'}; drops ${l.dropped.map(id=>labels[id]).join(', ')||'nothing'}.`).join('\n\n')}\n\nDecision rule: ${r.decision.reasons.join(' ')}\n\nSource facts:\n${factIds.map(id=>`- ${labels[id]}: ${valueText(id,state.facts[id])}; cost ${state.costs[id]}; ${r.available.includes(id)?'available at decision':`absent after ${layerNames[r.lostAt[id]]}`}`).join('\n')}${c?`\n\nPinned reporting arrangement replayed on current facts: ${summary(state,c.result)}`:''}\n\nFacts are selected whole, in priority order, while they fit. Later layers cannot recover omitted facts; explicit retrieval can. Reading cost is a stated attention assumption. No language understanding, deception or persuasion is simulated. Full-information output is this same rule with every fact, not an objective verdict.\n\nInspired by John Cutler, AI and the Recontextualization Tax: https://cutlefish.substack.com/p/tbm-437-ai-and-the-recontextualization\n`;}
